{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Trifluoperazine, a phenothiazine with a basic piperazine side chain, has a measured log BB of 1.44 and is classified as BBB-permeable by passive diffusion, demonstrating that ionizable basic phenothiazines can achieve high brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlorpromazine, a chloro-phenothiazine with a basic dimethylaminopropyl side chain, has a log BB of 1.06 and is considered to cross the BBB by passive diffusion, supporting meaningful CNS access for this scaffold despite basic ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Fluphenazine, a trifluoromethyl-phenothiazine with a basic hydroxyethylpiperazine side chain, has a log BB of 1.51 and passive BBB transport, further establishing the phenothiazine class as CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Perphenazine, another N-substituted phenothiazine, reaches maximal brain concentrations 2-4 hours after intraperitoneal dosing in mice, confirming meaningful brain bioavailability for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Dixyrazine, a phenothiazine with a basic side chain, penetrates rapidly into human CSF with a CSF/plasma ratio of 0.3, providing direct human evidence of CNS access for phenothiazine derivatives.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a methylthio-phenothiazine with a basic N-(piperidinylpropyl) side chain, closely analogous to CNS-active phenothiazine antipsychotics. Multiple direct in vivo measurements show high log BB, rapid brain uptake, and human CSF penetration for this scaffold despite basic amine ionization; therefore meaningful CNS access is expected.",
  "evidence_gaps": [
    "No direct in vivo measurement for the exact query or thioridazine itself is present in the evidence set.",
    "Efflux transporter liability for the query is inferred rather than directly measured; phenothiazines can be transporter substrates yet still achieve meaningful brain exposure.",
    "A discordant human CSF observation for trimeprazine (C09) was not used as a primary anchor because of structural and methodological differences."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

